CREATE TABLE t3(a,b PRIMARY KEY) WITHOUT ROWID; WITH RECURSIVE nums(value) AS (VALUES(1) UNION ALL SELECT value+1 FROM nums WHERE value<199) INSERT INTO t3(a,b) SELECT value,value FROM nums; UPDATE t3 SET a=999 WHERE b%5!=0; CREATE UNIQUE INDEX t3a ON t3(a) WHERE a<>999; INSERT INTO t3(a,b) VALUES(999,'test1'),(999,'test2'); VACUUM;